// specs/data/spec.md — MORA/SharePoint source adapter. One row per prayer time.
import type { District } from './core.js'

/** Public canonical page the app links to (the prod host is internal-only). */
export const MORA_PAGE_URL =
  'https://www.mora.gov.bn/SitePages/WaktuSembahyang.aspx'
export const MORA_API_URL = 'https://www.mora.gov.bn'

const LIST_PATH = "/_api/web/lists/getbytitle('Waktu%20Sembahyang')/items"
const BRUNEI_OFFSET_MS = 8 * 60 * 60 * 1000

/** Source labels, ordered as shown on the MORA page. */
export const MORA_PRAYERS = [
  { prayer: 'imsak', label: 'Imsak', meridiem: 'am' },
  { prayer: 'subuh', label: 'Suboh', meridiem: 'am' },
  { prayer: 'syuruk', label: 'Syuruk', meridiem: 'am' },
  { prayer: 'doha', label: 'Doha', meridiem: 'am' },
  { prayer: 'zuhur', label: 'Zohor', meridiem: 'noon' },
  { prayer: 'asar', label: 'Asar', meridiem: 'pm' },
  { prayer: 'maghrib', label: 'Maghrib', meridiem: 'pm' },
  { prayer: 'isyak', label: 'Isyak', meridiem: 'pm' },
] as const

export type MoraPrayer = (typeof MORA_PRAYERS)[number]['prayer']

export interface MoraItem {
  Title?: string
  Date: string
  Tarikh?: string
  Imsak?: string
  Suboh?: string
  Syuruk?: string
  Doha?: string
  Zohor?: string
  Asar?: string
  Maghrib?: string
  Isyak?: string
}

export interface PrayerTimeRecord {
  prayerDate: string
  district: District
  prayer: MoraPrayer
  time: string
  hijriDate: string
  sourceUrl: string
}

export interface MoraRange {
  /** Inclusive SharePoint filter bound (UTC). */
  fromIso: string
  /** Exclusive SharePoint filter bound (UTC). */
  toIso: string
}

/**
 * One Brunei calendar month, expressed as the UTC bounds SharePoint stores
 * Brunei dates in (local midnight = previous day 16:00 UTC). MORA is imported
 * monthly, manually; shells never read it at runtime.
 */
export function moraMonthRange(year: number, month: number): MoraRange {
  return {
    fromIso: new Date(Date.UTC(year, month - 1, 1) - BRUNEI_OFFSET_MS).toISOString(),
    toIso: new Date(Date.UTC(year, month, 1) - BRUNEI_OFFSET_MS).toISOString(),
  }
}

/** Brunei calendar year/month for an instant (UTC+8, no DST). */
export function bruneiYearMonth(now: Date = new Date()): {
  year: number
  month: number
} {
  const local = new Date(now.getTime() + BRUNEI_OFFSET_MS)
  return { year: local.getUTCFullYear(), month: local.getUTCMonth() + 1 }
}

export function moraItemsUrl(range: MoraRange): string {
  const filter = `Date ge datetime'${range.fromIso}' and Date lt datetime'${range.toIso}'`
  return `${MORA_API_URL}${LIST_PATH}?$select=Title,Date,Tarikh,Imsak,Suboh,Syuruk,Doha,Zohor,Asar,Maghrib,Isyak&$filter=${encodeURIComponent(filter)}&$orderby=Date asc&$top=5000`
}

/** SharePoint's Date is local midnight stored as UTC, so shift to Brunei. */
export function moraDateToLocalDate(iso: string): string {
  const time = Date.parse(iso)
  if (Number.isNaN(time)) throw new Error(`Invalid MORA date: ${iso}`)
  return new Date(time + BRUNEI_OFFSET_MS).toISOString().slice(0, 10)
}

/** "3.23" + Asar => "15:23"; "12.11" + Zohor => "12:11". */
export function moraTimeTo24Hour(
  prayer: MoraPrayer,
  raw: string,
): string | null {
  const value = raw.trim()
  if (!value || value === '-') return null
  const match = /^(\d{1,2})[.:](\d{2})$/.exec(value)
  if (!match) throw new Error(`Invalid MORA time for ${prayer}: ${raw}`)
  let hour = Number(match[1])
  const minute = Number(match[2])
  if (hour > 23 || minute > 59) {
    throw new Error(`Invalid MORA time for ${prayer}: ${raw}`)
  }
  const meridiem = MORA_PRAYERS.find((entry) => entry.prayer === prayer)?.meridiem
  if (meridiem === 'pm' && hour < 12) hour += 12
  if (meridiem === 'am' && hour === 12) hour = 0
  return `${String(hour).padStart(2, '0')}:${String(minute).padStart(2, '0')}:00`
}

/** Normalizes raw SharePoint items into one record per prayer time. */
export function normalizeMoraItems(
  items: readonly MoraItem[],
  district: District = 'bruneiMuara',
): PrayerTimeRecord[] {
  const records: PrayerTimeRecord[] = []
  for (const item of items) {
    const prayerDate = moraDateToLocalDate(item.Date)
    const hijriDate = item.Tarikh?.trim() ?? ''
    for (const { prayer, label } of MORA_PRAYERS) {
      const raw = item[label as keyof MoraItem]
      if (typeof raw !== 'string') continue
      const time = moraTimeTo24Hour(prayer, raw)
      if (!time) continue
      records.push({
        prayerDate,
        district,
        prayer,
        time,
        hijriDate,
        sourceUrl: MORA_PAGE_URL,
      })
    }
  }
  return records
}

export async function fetchMoraItems(
  range: MoraRange,
  fetchImpl: typeof fetch = fetch,
): Promise<MoraItem[]> {
  const response = await fetchImpl(moraItemsUrl(range), {
    headers: { Accept: 'application/json;odata=nometadata' },
  })
  if (!response.ok) {
    throw new Error(`MORA request failed: ${response.status} ${response.statusText}`)
  }
  const body = (await response.json()) as { value?: MoraItem[] }
  return body.value ?? []
}

/** SQL seed with the same upsert semantics as the REST import. */
export function toSql(records: readonly PrayerTimeRecord[]): string {
  const quote = (value: string) => `'${value.replaceAll("'", "''")}'`
  const values = records.map(
    (record) =>
      `  (${quote(record.prayerDate)}, ${quote(record.district)}, ` +
      `${quote(record.prayer)}, ${quote(record.time)}, ` +
      `${quote(record.hijriDate)}, ${quote(record.sourceUrl)})`,
  )
  return [
    `-- Seed: MORA/KHEU prayer times, ${records[0]?.prayerDate} .. ${records.at(-1)?.prayerDate}.`,
    '-- One row per prayer time; regenerate with `pnpm import:mora --sql`.',
    'insert into public.prayer_times',
    '  (prayer_date, district, prayer, time, hijri_date, source_url)',
    'values',
    values.join(',\n'),
    'on conflict (prayer_date, district, prayer) do update set',
    '  time = excluded.time,',
    '  hijri_date = excluded.hijri_date,',
    '  source_url = excluded.source_url,',
    '  updated_at = now();',
    '',
  ].join('\n')
}
